 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # A 5-line is a ruler: copy the colored tile attached to its end
    # along the length of the ruler.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 5:
                c += 1
                continue
            a = c
            while c < w and grid[r][c] == 5:
                c += 1
            b = c - 1
            if b - a + 1 < 2:
                continue
            # Seed is the non-5 colored strip below either endpoint.
            for anchor in (a, b):
                rr = r + 1
                vals = []
                while rr < h and grid[rr][anchor] not in (0, 5):
                    vals.append(grid[rr][anchor])
                    rr += 1
                if vals:
                    for x in range(a, b + 1):
                        for k, v in enumerate(vals):
                            y = r + 1 + k
                            if y < h and grid[y][x] == 0:
                                out[y][x] = v

    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5:
                r += 1
                continue
            a = r
            while r < h and grid[r][c] == 5:
                r += 1
            b = r - 1
            if b - a + 1 < 2:
                continue
            # Seed to the right of the ruler, attached near its lower end.
            # Use the contiguous rectangular colored block at the bottom
            # as the tile, then repeat it vertically along the ruler.
            right = c + 1
            if right >= w:
                continue
            seed_end = b
            # Locate colored rows in the right-hand area adjoining the line.
            rows = [y for y in range(a, b + 1)
                    if grid[y][right] not in (0, 5)]
            if not rows:
                continue
            seed_start = min(rows)
            seed_end = max(rows)
            # Seed width is the contiguous colored run in the bottom seed row.
            x = right
            while x < w and grid[seed_end][x] not in (0, 5):
                x += 1
            seed_width = x - right
            if seed_width <= 0:
                continue
            tile_h = seed_end - seed_start + 1
            tile = [grid[y][right:right + seed_width] for y in range(seed_start, seed_end + 1)]
            for y in range(a, b + 1):
                pattern = tile[(y - seed_start) % tile_h]
                for k, v in enumerate(pattern):
                    x = right + k
                    if grid[y][x] == 0:
                        out[y][x] = v

    # Vertical-color seed beneath a horizontal 5 bar (transpose of the
    # horizontal ruler operation). Repeat the seed column across the bar.
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5:
                r += 1
                continue
            a = r
            while r < h and grid[r][c] == 5:
                r += 1
            b = r - 1
            if b - a + 1 < 2 or b + 1 >= h:
                continue
            vals = []
            y = b + 1
            while y < h and grid[y][c] not in (0, 5):
                vals.append(grid[y][c])
                y += 1
            if vals:
                for x in range(c, min(w, c + (b - a + 1))):
                    for k, v in enumerate(vals):
                        yy = b + 1 + k
                        if yy < h and grid[yy][x] == 0:
                            out[yy][x] = v
    return out


